{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Fenspiride absolute oral bioavailability was 90% in healthy volunteers after an 80 mg slow-release tablet versus IV, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Vildagliptin absolute oral bioavailability was approximately 85% in healthy volunteers after 50 mg oral versus 25 mg IV, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Pentazocine absolute oral bioavailability was 18% in healthy subjects after 100 mg tablets versus IV, below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "High is better supported: most transferred molecules have absolute oral bioavailability well above 20%, while only pentazocine falls below; the contradictory pentazocine evidence is direct but outweighed by the consistent high-F evidence.",
  "evidence_gaps": [
    "Pentazocine is a direct, condition-matched contradictory case with mean absolute bioavailability about 18%, below the 20% threshold.",
    "Some positive records are not explicitly absolute (e.g., anagliptin, thalidomide), though their numeric values are far above the threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

